descriptor.templateCss:
.ov{
  height:100%;box-sizing:border-box;padding:12px 15px;border-radius:14px;background:#fff;
  border:1px solid #dfe7ef;color:#111827;font-family:"OpenAI Sans", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  display:flex;align-items:center;gap:18px;box-shadow:0 1px 3px rgba(15,23,42,.04)
}
.ov-brand{min-width:230px}
.ov-title{font-size:20px;line-height:1.2;font-weight:650;letter-spacing:-.025em;color:#0f172a}
.ov-sub{display:flex;align-items:center;gap:7px;font-size:11.5px;color:#64748b;margin-top:4px;white-space:nowrap}
.live-dot{width:8px;height:8px;border-radius:999px;background:#94a3b8;box-shadow:0 0 0 3px rgba(148,163,184,.12)}
.live-dot.ok{background:#12b76a;box-shadow:0 0 0 3px rgba(18,183,106,.12)}
.live-dot.bad{background:#f04438;box-shadow:0 0 0 3px rgba(240,68,56,.12)}
.ov-items{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;flex:1}
.ov-chip{min-width:0;height:45px;padding:0 10px;border-radius:11px;border:1px solid #e5e7eb;display:flex;flex-direction:column;justify-content:center;gap:2px;overflow:hidden;background:#f8fafc}
.ov-chip span{font-size:9.5px;line-height:1.1;color:#64748b}
.ov-chip b{font-size:11.5px;line-height:1.15;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#0f172a}
.ov-chip.ok{background:#ecfdf3;border-color:#abefc6}.ov-chip.ok b{color:#067647}
.ov-chip.warn{background:#fffaeb;border-color:#fedf89}.ov-chip.warn b{color:#b54708}
.ov-chip.bad{background:#fef3f2;border-color:#fecdca}.ov-chip.bad b{color:#b42318}
.ov-chip.neutral{background:#ecfeff;border-color:#cffafe}.ov-chip.neutral b{color:#0e7490}
@media(max-width:900px){
 .ov{align-items:flex-start;flex-direction:column;gap:9px}
 .ov-brand{min-width:0}
 .ov-items{grid-template-columns:repeat(3,minmax(0,1fr));width:100%}
}
@media(max-width:599px){
 .ov{padding:11px;border-radius:12px}
 .ov-title{font-size:18px}
 .ov-sub{white-space:normal}
 .ov-items{grid-template-columns:repeat(2,minmax(0,1fr))}
 .ov-chip{height:43px}
}

descriptor.controllerScript:
var tgOverviewTimer;

function tgLatestValue(name) {
  var rows = self.ctx.data || [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row.dataKey || row.dataKey.name !== name || !row.data || !row.data.length) {
      continue;
    }
    var newest = row.data[0];
    for (var j = 1; j < row.data.length; j++) {
      if (row.data[j][0] > newest[0]) { newest = row.data[j]; }
    }
    return newest[1];
  }
  return null;
}

function tgBool(value) {
  return value === true || value === 1 || value === '1' || value === 'true';
}

function tgAgeText(lastActivity) {
  if (!Number.isFinite(lastActivity) || lastActivity <= 0) return 'chưa có hoạt động';
  var sec = Math.max(0, Math.floor((Date.now() - lastActivity) / 1000));
  if (sec < 5) return 'vừa cập nhật';
  if (sec < 60) return 'cập nhật ' + sec + ' giây trước';
  var min = Math.floor(sec / 60);
  if (min < 60) return 'cập nhật ' + min + ' phút trước';
  var hr = Math.floor(min / 60);
  return 'cập nhật ' + hr + ' giờ trước';
}

function tgOverviewRender() {
  var scope = self.ctx.$scope;
  var active = tgBool(tgLatestValue('active'));
  var lastActivity = Number(tgLatestValue('lastActivityTime'));
  var freshness = Math.max(10000, Number(self.ctx.settings.onlineFreshnessMs || 30000));
  var age = Number.isFinite(lastActivity) && lastActivity > 0 ? (Date.now() - lastActivity) : null;
  var online = active && (age === null || age <= freshness);

  var sos = tgBool(tgLatestValue('sos_pending'));
  var person = tgBool(tgLatestValue('person_detected'));
  var gps = tgLatestValue('gps_state');
  var gpsText = gps == null ? '--' : String(gps);
  var gpsUpper = gpsText.toUpperCase();
  var net = tgBool(tgLatestValue('network_registered'));
  var speed = Number(tgLatestValue('speed_kmh'));

  scope.systemText = online ? 'ONLINE' : 'OFFLINE';
  scope.systemClass = online ? 'ok' : 'bad';
  scope.lastSeenText = tgAgeText(lastActivity);

  scope.sosText = sos ? 'ĐANG CHỜ XỬ LÝ' : 'BÌNH THƯỜNG';
  scope.sosClass = sos ? 'bad' : 'ok';

  scope.radarText = person ? 'PHÁT HIỆN NGƯỜI' : 'KHÔNG PHÁT HIỆN';
  scope.radarClass = person ? 'warn' : 'ok';

  scope.gpsText = gpsText;
  if (gpsUpper.indexOf('FIXED') >= 0 || gpsUpper === 'FIX' || gpsUpper === 'GPS_OK') {
    scope.gpsClass = 'ok';
  } else if (gpsUpper.indexOf('FAULT') >= 0 || gpsUpper.indexOf('ERROR') >= 0) {
    scope.gpsClass = 'bad';
  } else {
    scope.gpsClass = 'warn';
  }

  scope.networkText = net ? 'ONLINE' : 'OFFLINE';
  scope.networkClass = net ? 'ok' : 'bad';
  scope.speedText = Number.isFinite(speed) ? speed.toFixed(1) + ' km/h' : '--';

  if (scope.$evalAsync) { scope.$evalAsync(); }
}

self.onInit = function() {
  tgOverviewRender();
  tgOverviewTimer = window.setInterval(tgOverviewRender, 1000);
};

self.onDataUpdated = function() {
  tgOverviewRender();
};

self.typeParameters = function() {
  return {
    maxDatasources: 1,
    dataKeysOptional: false,
    singleEntity: true,
    previewWidth: '1000px',
    previewHeight: '150px'
  };
};

self.onDestroy = function() {
  if (tgOverviewTimer) {
    window.clearInterval(tgOverviewTimer);
    tgOverviewTimer = null;
  }
};
